<template><BaseCard><h2 class='text-xl mb-4'>Novo Prontuário</h2><form class='grid md:grid-cols-2 gap-3' @submit.prevent='submit'><BaseInput v-for='f in fields' :key='f' v-model='form[f]' :placeholder='f'/><div class='md:col-span-2'><BaseButton>Salvar</BaseButton></div></form><p v-if='createdId' class='mt-2'>Criado! <router-link :to='`/medical-records/${createdId}`'>Abrir</router-link></p><ErrorState v-if='error' :message='error'/></BaseCard></template>
<script setup>import { reactive,ref } from 'vue';import { medicalRecordService } from '../services/medicalRecordService';import BaseCard from '../components/BaseCard.vue';import BaseInput from '../components/BaseInput.vue';import BaseButton from '../components/BaseButton.vue';import ErrorState from '../components/ErrorState.vue';
const fields=['patient_id','appointment_id','anamnesis','physical_exam','diagnostic_hypothesis','diagnosis','conduct','prescriptions','exams_requested','evolution'];const form=reactive(Object.fromEntries(fields.map(f=>[f,''])));const createdId=ref('');const error=ref('');
const submit=async()=>{try{error.value='';const d=await medicalRecordService.create(form);createdId.value=d.id||d.medical_record_id}catch{error.value='Erro ao criar prontuário'}}
</script>
